using EvoWorld.Core.Random;
using Xunit;

namespace EvoWorld.Tests;

public class Pcg32Tests
{
    // Independently generated by compiling the unmodified official PCG C basic source:
    // https://github.com/imneme/pcg-c-basic/tree/bc39cd76ac3d541e618606bcc6e1e5ba5e5e6aa3
    // pcg32_srandom_r(seed, initseq=1), then ten pcg32_random_r calls.
    // Includes initialization state and overflow fixtures from the same C execution.
    public static TheoryData<ulong, ulong, uint[]> GoldenSequences => new()
    {
        { 0UL, 0x08f5dc87e5c07d8aUL,
            [0x0f5deba9U, 0x184296ddU, 0x357643f4U, 0xf8e84c31U, 0xaac1ca89U,
             0x4555f003U, 0x24d8217aU, 0x3e18cb9cU, 0x537b339dU, 0xe981425eU] },
        { 1UL, 0x6147d0b53255fcb7UL,
            [0xc9828f91U, 0x1592e274U, 0xc0262657U, 0xa5c2b6d3U, 0xaf811256U,
             0x6c1c2879U, 0x30130b26U, 0x9cc21c33U, 0xd137ef42U, 0x908262abU] },
        { 42UL, 0x8667ebf676475aecUL,
            [0x4df1ccf9U, 0xe5838752U, 0x58ed9e10U, 0xf3e37b51U, 0xe7664374U,
             0x6afde4a8U, 0x8712391eU, 0x738fc318U, 0x0b1f9c57U, 0x41b0f580U] },
        { 12345678901234567890UL, 0x32fdb22344cd9274UL,
            [0x157edf4eU, 0xc7ac9e87U, 0xedf0493aU, 0xb3e0288dU, 0xf777dcfdU,
             0x7269d364U, 0x61b92664U, 0x239812beU, 0xb1f730acU, 0x3f6988beU] },
        { ulong.MaxValue, 0xb0a3e85a992afe5dUL,
            [0xe2393051U, 0xd4ee9aa6U, 0x724075bdU, 0xdbc6f13bU, 0xbfc7dd95U,
             0x7b2d3585U, 0x07f0a249U, 0xdcb78f67U, 0x86cf0e77U, 0xaa9871faU] }
    };

    [Theory]
    [MemberData(nameof(GoldenSequences))]
    public void InitializationAndFirstTenOutputsMatchOfficialReference(
        ulong seed, ulong initializedState, uint[] expected)
    {
        var generator = new Pcg32(seed);

        Assert.Equal(new Pcg32State(initializedState, 3UL), generator.CaptureState());
        Assert.Equal(expected, ReadOutputs(generator, 10));
    }

    [Fact]
    public void ZeroSeedFirstOutputMatchesOfficialReference()
    {
        Assert.Equal(0x0f5deba9U, new Pcg32(0UL).NextUInt());
    }

    [Fact]
    public void SameSeedProducesSameSequenceAcrossRepeatedRuns()
    {
        var expected = ReadOutputs(new Pcg32(42UL), 1000);

        for (var run = 0; run < 3; run++)
            Assert.Equal(expected, ReadOutputs(new Pcg32(42UL), 1000));
    }

    [Fact]
    public void RepresentativeDifferentSeedsProduceDifferentSequences()
    {
        var zero = ReadOutputs(new Pcg32(0UL), 10);
        var one = ReadOutputs(new Pcg32(1UL), 10);
        var fortyTwo = ReadOutputs(new Pcg32(42UL), 10);

        Assert.False(zero.SequenceEqual(one));
        Assert.False(zero.SequenceEqual(fortyTwo));
        Assert.False(one.SequenceEqual(fortyTwo));
    }

    [Fact]
    public void CapturingDoesNotAdvanceGenerator()
    {
        var generator = new Pcg32(42UL);
        var before = generator.CaptureState();

        Assert.Equal(before, generator.CaptureState());
        Assert.Equal(0x4df1ccf9U, generator.NextUInt());
    }

    [Fact]
    public void RepeatedRestorationReproducesExactContinuation()
    {
        var generator = new Pcg32(42UL);
        ReadOutputs(generator, 37);
        var snapshot = generator.CaptureState();
        var expected = ReadOutputs(generator, 100);

        for (var restoration = 0; restoration < 3; restoration++)
        {
            generator.RestoreState(snapshot);
            Assert.Equal(snapshot, generator.CaptureState());
            Assert.Equal(expected, ReadOutputs(generator, 100));
        }
    }

    [Fact]
    public void SnapshotCanBeRestoredIntoAnotherGeneratorWithoutConsumingOutputs()
    {
        var original = new Pcg32(1UL);
        ReadOutputs(original, 53);
        var snapshot = original.CaptureState();
        var restored = new Pcg32(999UL);

        restored.RestoreState(snapshot);

        Assert.Equal(snapshot, restored.CaptureState());
        Assert.Equal(ReadOutputs(original, 100), ReadOutputs(restored, 100));
    }

    [Theory]
    [InlineData(0UL)]
    [InlineData(1UL)]
    [InlineData(2UL)]
    [InlineData(4UL)]
    [InlineData(5UL)]
    [InlineData(ulong.MaxValue)]
    public void InvalidIncrementIsRejectedWithoutChangingState(ulong increment)
    {
        var generator = new Pcg32(42UL);
        ReadOutputs(generator, 7);
        var before = generator.CaptureState();

        var exception = Assert.Throws<ArgumentException>(
            () => generator.RestoreState(new Pcg32State(123UL, increment)));

        Assert.Equal("state", exception.ParamName);
        Assert.Equal(before, generator.CaptureState());
    }

    [Fact]
    public void ZeroInternalStateIsAcceptedWithoutReseeding()
    {
        var generator = new Pcg32(42UL);
        var snapshot = new Pcg32State(0UL, 3UL);

        generator.RestoreState(snapshot);

        Assert.Equal(snapshot, generator.CaptureState());
        Assert.Equal(0U, generator.NextUInt());
        Assert.Equal(new Pcg32State(3UL, 3UL), generator.CaptureState());
    }

    [Fact]
    public void MaximumInternalStateWrapsExactlyAsOfficialReference()
    {
        var generator = new Pcg32(0UL);
        generator.RestoreState(new Pcg32State(ulong.MaxValue, 3UL));

        Assert.Equal(0xfff00001U, generator.NextUInt());
        Assert.Equal(new Pcg32State(0xa7ae0bd2b36a80d6UL, 3UL), generator.CaptureState());
    }

    private static uint[] ReadOutputs(Pcg32 generator, int count)
    {
        var outputs = new uint[count];
        for (var i = 0; i < count; i++)
            outputs[i] = generator.NextUInt();
        return outputs;
    }
}
